typedef struct native_sdk_gtk_native_view {
    HonkAccessibility *honk_accessibility;
    guint honk_accessibility_timer;

static void honk_accessibility_bounds(native_sdk_gtk_native_view_t *view) {
#ifdef GDK_WINDOWING_X11
    if (!view || !view->widget || !view->honk_accessibility) return;
    GtkNative *native = gtk_widget_get_native(view->widget);
    GdkSurface *surface = native ? gtk_native_get_surface(native) : NULL;
    if (!surface || !GDK_IS_X11_SURFACE(surface)) return; // Wayland has no global position.
    Display *display = gdk_x11_display_get_xdisplay(gdk_surface_get_display(surface));
    Window child = None;
    int x = 0, y = 0;
    if (!XTranslateCoordinates(display, gdk_x11_surface_get_xid(surface), DefaultRootWindow(display), 0, 0, &x, &y, &child)) return;
    graphene_point_t origin = {0}, point = {0};
    if (!gtk_widget_compute_point(view->widget, GTK_WIDGET(native), &origin, &point)) return;
    double scale = gtk_widget_get_scale_factor(view->widget);
    honk_a11y_bounds(view->honk_accessibility, x + point.x * scale, y + point.y * scale,
        gtk_widget_get_width(view->widget) * scale, gtk_widget_get_height(view->widget) * scale);
#else
    (void)view;
#endif
}

static gboolean honk_accessibility_poll(gpointer data) {
    native_sdk_gtk_native_view_t *view = data;
    if (!view || !view->honk_accessibility || !view->window || !view->label) return G_SOURCE_REMOVE;
    honk_accessibility_bounds(view);
    HonkAccessibilityAction action = {0};
    if (honk_a11y_poll(view->honk_accessibility, &action)) {
        // Runtime callbacks may close the view. Do not access it after dispatch.
        native_sdk_emit(view->window->host, (native_sdk_gtk_event_t){
            .kind = (native_sdk_gtk_event_kind_t)18,
            .window_id = view->window->id,
            .view_label = view->label,
            .view_label_len = strlen(view->label),
            .frame_index = action.id,
            .input_kind = action.action,
            .input_text = (const char *)action.text,
            .input_text_len = action.text_len,
        });
    }
    return G_SOURCE_CONTINUE;
}

